module parity_8bit (
    input [7:0] in,
    output out
);

    assign out = 
        |({in[1], in[0]} & |({in[3], in[0]})) || 
        |({in[5], in[1]}) || 
        |({in[4], in[6]}) || 
        |({in[7], in[6]}});

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    wire w1, w2, w3, w4, w5, w6;

    assign w1 = |{in[1], in[0]};
    assign w2 = ~(|{in[3], in[2]});
    assign w3 = w1 | w2;

    assign w4 = |{in[5], in[4]};
    assign w5 = ~(|{in[7], in[6]});
    assign w6 = w4 | w5;

    assign out = w3 | w6;

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    wire w0, w1, w2, w3, w4, w5, w6, w7;
    wire w8, w9, w10;

    assign w0 = in[0] | in[1];
    assign w1 = ~(in[2] | in[3]);
    assign w2 = w0 | w1;
    assign w3 = in[4] | in[5];
    assign w4 = ~(in[6] | in[7]);
    assign w5 = w3 | w4;
    assign out = w2 | w5;

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    wire [7:0] bus;
    assign bus = in;

    wire w0;
    wire w1;
    wire w2;
    wire w3;
    wire w4;

    assign w0 = ~(bus[0] & bus[1]);
    assign w1 = ~(bus[2] & bus[3]);
    assign w2 = ~(bus[4] & bus[5]);
    assign w3 = ~(bus[6] & bus[7]);
    assign w4 = ((~w0) | w1) | ((~w2) | w3);

    assign out = w4;

endmodule

module logic_gate_module(
    input [7:0] in,
    output out
);
    wire a, b, c, d, e, f, g, h;

    assign a = ~in[7];
    assign b = in[7] | in[6];
    assign c = in[7] & in[2];
    assign d = in[5] ^ in[6];
    assign e = in[5] | in[0];
    assign f = in[5] | in[4];
    assign g = in[3] | in[2];
    assign h = in[5] ^ in[6];

    assign out = (a) | (b) | (c) | (d) | (e) | (f) | (g) | (h);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

assign out = (
    {!sel[0] | &in} &
    (!sel[1] & ~in[1]) &
    (!sel[0] & ~in[1]) &
    (!sel[1] & ~in[2]) &
    ({!sel[1] & !in[2]} & {!sel[0] | in[3]})
) ? 1'h1 : 1'h0;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_val0_1 = ~in[1];
    wire not_val0_2 = ~in[2];
    wire not_val1_0 = ~sel[0];
    wire result1 = ~(in[1] & ~sel[0] & in[0]);
    wire result2 = in[0] & in[1];
    wire result3 = ~(in[0] & in[3]);
    wire result4 = in[3] & in[1];
    wire result5 = result2 & NOT(result2);
    wire result6 = in[2] & NOT(sel[0]);
    wire result7 = ~(NOT(sel[0]) & NOT(in[1]) & NOT(in[0]));
    wire result8 = ~(result1 & result3);
    wire result9 = ~(in[2] & result5);
    assign out = result8 & result9;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12, w13, w14;

    assign w1 = ~sel[0];
    assign w2 = in[0] & w1;
    assign w3 = sel[0] & in[1];
    assign w4 = in[1] & sel[1];
    assign w5 = in[2] & sel[1];
    assign w6 = in[3] & sel[0];
    assign w7 = w1 & in[0];
    assign w8 = w3 & w4;
    assign w9 = in[0] & sel[0];
    assign w10 = in[1] & sel[0];
    assign w11 = in[2] & sel[0];
    assign w12 = in[3] & sel[0];
    assign w13 = ~w2;
    assign w14 = w5 | w6;

    assign out = (w8 & w14) | ((w9 & w10) & (w11 & w12)) | (w7 & sel[0]);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
