    assign out = (sel[0] & !sel[1] & in[0] & in[1]) |
                   ((sel[0] | sel[1]) & (in[0] | in[1]) & (in[2] | in[3])) |
                   ((sel[0] & in[0]) & (in[2] | in[3])) |
                   ((sel[1] & in[0]) & (in[2] | in[3]));
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire sel_0, sel_1, sel_2, sel_3;
    wire inv_sel_0;
    wire out_1b;
    wire out_2b;
    wire out_3b;
    wire out_4b;
    wire out_5b;
    wire temp_1;
    wire temp_2;
    wire temp_3;
    wire temp_4;

    assign sel_0 = !(sel[1]);
    assign sel_1 = (sel[1] & sel[0]);
    assign sel_2 = ~(sel[0]);
    assign sel_3 = sel[0];
    assign inv_sel_0 = ~sel_0;

    assign out_1b = (sel_0 & sel[0]) | (sel_1 & in[1]);
    assign out_2b = (sel_2 & ~in[0]) | (sel_1 & in[0]);
    assign out_3b = (sel_3 & ~(in[0] ^ in[1]));
    assign out_4b = (sel_2 & sel[0]) | (sel_3 & ~(in[0] ^ in[1]));
    assign out_5b = (sel_0 & ~(sel[1] & ~(in[1] & sel[0]))) | 
                    (sel_1 & ~(in[1] & ~(sel[1] & in[0])));

    assign temp_1 = out_1b & out_5b;
    assign temp_2 = out_2b & out_5b;
    assign temp_3 = out_3b & out_5b;
    assign temp_4 = out_4b & out_5b;

    assign out = (temp_1 | (temp_3 & temp_4));

endmodule

