module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

always @(*) begin
    if (in[0] == 1'b1) begin
        case (in[0])
            1'b1: out = {1'b1, &in[1:0]};
            default: out = {4'b0};
        endcase
    end else begin
        case (in[0])
            1'b0: out = {1'b0, |in[1:0]};
            default: out = {4'b0};
        endcase
    end
end

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    wire [1:0] mux_out;

    assign mux_out = in[0] ? in[1] : {1'b0, in[0]};

    assign out[0] = (~mux_out[0] & mux_out[1]) | (~mux_out[0] & ~mux_out[1]) | (~mux_out[1] & ~mux_out[0]);
    assign out[1] = (~mux_out[0] & mux_out[1]) | (~mux_out[0] & ~mux_out[1]) | (mux_out[0] & ~mux_out[1]);
    assign out[2] = (~mux_out[0] & ~mux_out[1]) | (mux_out[0] & ~mux_out[1]) | (mux_out[0] & mux_out[1]);
    assign out[3] = (mux_out[0] & ~mux_out[1]) | (~mux_out[0] & mux_out[1]) | (mux_out[0] & mux_out[1]);

endmodule

module decoder_2to4 (
    input [1:0] in,
