);

    // Assigning each bit of out based on the circuit diagram logic
    // For each bit i of out, it's the result of an AND operation between
    // two bits from in, depending on the position

    assign out[0] = (~in[0]) & in[1];
    assign out[1] = (~in[0]) & (~in[1]);
    assign out[2] = (~in[0]) & (~in[1]); // Actually, this is the same as out[1], but that's what the diagram shows
    assign out[3] = in[0] & in[1];

endmodule

