module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*)
begin
    // Gate 1: AND gate with inputs [2:1] of in
    wire w1 = (in[2] & in[1]) ? 1'b1 : 1'b0;

    // Gate 2: NAND gate with inputs w1 and [2] of in
    wire w2 = (~w1) | ~in[2];

    // Gate 3: AND gate with inputs [3] of in and w2
    wire w3 = in[3] & w2;

    // Gate 4: OR gate with inputs w3 and [1] of in
    wire w4 = w3 | in[1];

    // Output assignment
    code[0] = w2 & w3;
    code[1] = w4;
end

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
    always @(*) begin
        // From the circuit:
        // code[0] = NOT(in[2]) AND (in[3] AND (in[1] OR NOT(in[2])))
        // code[1] = in[3] AND (in[1] OR NOT(in[2]))

        code[0] = ~in[2] & (in[3] & (in[1] | ~in[2]));
        code[1] = in[3] & (in[1] | ~in[2]);
    end
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    wire node_a, node_b, node_c;

    // First AND gate: inputs from in[2] and in[3] -> output node_a
    node_a = in[2] & in[3];

    // Second AND gate: inputs from node_a and in[1] -> output node_b
    node_b = node_a & in[1];

    // Third AND gate: inputs from in[1] and in[0] -> output node_c
    node_c = in[1] & in[0];

    // Assign code[0] and code[1] based on the outputs
    code[0] = node_b;
    code[1] = node_c;
end

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    code = 2'b10;
end

// Replicate the circuit logic manually based on the diagram
// Inputs: in[2], in[3], in[1]
// Gates:
// Top path: NAND(in[2], NOT(in[2])) -> AND(NOT(in[2]), in[1]) -> AND(in[3], that_result) -> code[0]
// Wait, let me re-examine the diagram carefully.

// Looking at the connections:
// - Top gate: NAND with inputs: in[2] and NOT(in[2]) -> output is always 0? That can't be right.
// Actually, looking more carefully:
// The top NAND gate has:
//   Input 1: from in[2]
//   Input 2: from the NOT gate output (which is NOT(in[2]))
// This would make a NAND of X and NOT(X), which is always 1.

// Let me trace again from the diagram:
// There's a NOT gate connected to in[2]? No, looking at the diagram:
// The NOT gate is connected to in[1] (output of NOT is inverted signal from in[1])
// Actually, I think I misread. Let me try once more.

// From the diagram structure:
// - There's a NOT gate whose input comes from in[1] position? No...
// Looking at the black bar on left:
//   Position 2 -> goes to one input of top NAND
//   Position 3 -> goes to one input of two AND gates
//   Position 1 -> goes to NOT gate AND one input of bottom AND

// Now tracing:
// NOT gate input: in[1]
// NOT gate output: NOT(in[1]) -> goes to one input of bottom AND gate

// Top NAND gate:
//   Input 1: in[2]
//   Input 2: NOT(in[1])  [from the NOT gate]
//   Output of NAND: ~(in[2] & ~in[1]) -> goes to one input of top AND gate

// Bottom AND gate:
//   Input 1: in[2]
//   Input 2: NOT(in[1])
//   Output: in[2] & ~in[1]

// Top AND gate:
//   Input 1: output of top NAND = ~(in[2] & ~in[1])
//   Input 2: in[3]
//   Output: in[3] & ~(in[2] & ~in[1]) -> this is code[0]

// So:
// code[0] = in[3] & ~(in[2] & ~in[1])
// code[1] = output of bottom AND = in[2] & ~in[1]

assign code[0] = in[3] & ~((in[2] & ~in[1]));
assign code[1] = (in[2] & ~in[1]);

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] Q;
    wire NOT_val_0;
    wire AND_val_0_val_1;
    wire OR_Q_val_1;
    wire OR_Q_NOT_val_0;
    wire NAND_AND_val_0_val_1;

    assign NOT_val_0 = ~clk;
    assign AND_val_0_val_1 = clk & reset;
    assign OR_Q_val_1 = Q[1] | reset;
    assign OR_Q_NOT_val_0 = Q[0] | NOT_val_0;
    assign NAND_AND_val_0_val_1 = ~(AND_val_0_val_1);

    always @(posedge Q[0] or posedge OR_Q_val_1 or posedge OR_Q_NOT_val_0)
        if (OR_Q_val_1)
            Q[1] <= Q[0];
        else if (OR_Q_NOT_val_0)
            Q[0] <= Q[1];

    assign state[0] = Q[0];
    assign state[1] = Q[0] ? NAND_AND_val_0_val_1[1] : 1;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state;
    wire q1, q2;

    // First DFF
    always @(posedge clk or posedge rst) begin
        if (rst)
            q1 <= 0;
        else if (reset & q2)
            q1 <= !q1;
        else
            q1 <= q1;
    end

    // Second DFF
    always @(posedge clk or posedge rst) begin
        if (rst)
            q2 <= 0;
        else if (!reset & clk)
            q2 <= !q2;
        else
            q2 <= q2;
    end

    // MUX for state[0]
    assign state[0] = q1;

    // MUX for state[1]
    assign state[1] = q2 ? q1 : 0;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    wire q0, q1, a0, a1;

    // Top DFF
    assign S_SDFP_PP0_C = q1;
    assign S_SDFP_PP0_D = clk;
    assign S_SDFP_PP0_R = q0;
    assign q0 = S_SDFP_PP0_Q;

    // Bottom DFF
    assign S_SDFP_PP0_C = q0;
    assign S_SDFP_PP0_D = a0 ^ a1;
    assign S_SDFP_PP0_R = clk;
    assign q1 = S_SDFP_PP0_Q;

    // AND gate for a0
    assign a0 = clk & reset;

    // AND gate for a1
    assign a1 = ~q1 & reset;

    // MUX for state[1:0]
    assign state[1:0] = {1'b0, state[0]};
    assign state[0] = q0 | ((q1) ? q0 : a0);

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg Q0;
reg Q1;

always @(posedge 0) begin
    if (reset & (clk | Q1))
        Q0 <= ~Q1;
    Q1 <= (Q0 & Q1) | (clk & ~Q1);
end

assign state[0] = Q1;
assign state[1] = Q0;

endmodule

