module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);
    wire[1:0] sel_val;
    reg        q;
    reg [3:0]  temp;

    always @(*) begin
        case (in)
            2'd0: begin
                sel_val = 2'b00;
                q       = 0;
                temp    = 4'b0000;
            end
            2'd1: begin
                sel_val = 2'b00;
                q       = 0;
                temp    = 4'b0100;
            end
            2'd2: begin
                sel_val = 2'b00;
                q       = 0;
                temp    = 4'b1000;
            end
            2'd3: begin
                sel_val = 2'b00;
                q       = 0;
                temp    = 4'b1100;
            end
            default: begin
                sel_val = 2'b00;
                q       = 0;
                temp    = 4'b0000;
            end
        endcase
    end

    assign out = {q, !q};
    assign valid = temp[3] & temp[2];

    // Mux logic for sel_val
    always @(*) begin
        case (in)
            2'd0: sel_val[1] = in[1]; sel_val[0] = in[1];
            2'd1: sel_val[1] = in[0]; sel_val[0] = in[1];
            2'd2: sel_val[1] = in[1]; sel_val[0] = in[0];
            2'd3: sel_val[1] = in[0]; sel_val[0] = in[0];
        endcase
        q = (sel_val[1] & sel_val[0]) ? 0 : (sel_val[1] & ~sel_val[0]) ? 1 : ( ~sel_val[1] & sel_val[0]) ? 0 : ( ~sel_val[1] & ~sel_val[0]) ? 1 : 0;
    end

endmodule

