    if(s_Sdff_PP0_2)
        s_Sdff_PP0_2 <= clk & ~s_Sdff_PP0_0;
    if(s_Sdff_PP0_3)
        s_Sdff_PP0_3 <= clk & ~s_Sdff_PP0_1;
    if(s_Sdff_PP1_0)
        s_Sdff_PP1_0 <= clk & ~s_Sdff_PP0_0;
    if(s_Sdff_PP1_1)
        s_Sdff_PP1_1 <= rst & ~s_Sdff_PP0_1;
    if(s_Sdff_PP0_1) begin
        s_Sdff_PP0_1 <= rst & ~s_Sdff_PP0_0;
        s_Sdff_PP0_0 <= clk;
        s_Sdff_PP0_2 <= clk;
        s_Sdff_PP0_3 <= clk;
        s_Sdff_PP1_0 <= clk;
        s_Sdff_PP1_1 <= rst;
    end
end

assign q[0] = s_Sdff_PP1_1;
assign q[1] = s_Sdff_PP1_0;
assign q[2] = s_Sdff_PP0_3;
assign q[3] = s_Sdff_PP0_2;

