  input [1:0] byteena,
  input [15:0] d,
  output reg [15:0] q
);
  // Synchronous register array with parallel load
  reg [15:0] temp;

  always @(posedge clk) begin
    // Initialize all registers to 16'b0
    temp <= 16'b0;

    // Parallel load based on byteena
    if (byteena[1] & byteena[0])
      temp <= 16'b1111111111111111; // All 1s
    else if (byteena[1] & ~byteena[0])
      temp <= 16'b1000000000000000; // 1 followed by 15 zeros
    else if (~byteena[1] & byteena[0])
      temp <= {16{d[7]}}; // Repeat d[7] 16 times
    // Otherwise: do nothing (holds previous state)
  end

  // Output assignment - shift and select based on d
  always @(posedge clk) begin
    // Map d bits to output position
    case (d[15:13])
      3'b000: q <= temp[15];
      3'b001: q <= temp[14];
      3'b010: q <= temp[13];
      3'b011: q <= temp[12];
      3'b100: q <= temp[11];
      3'b101: q <= temp[10];
      3'b110: q <= temp[9];
      3'b111: q <= temp[8];
      // For other cases, hold previous value
    endcase
  end

  // Simplified version matching the diagram structure
  always @(posedge clk) begin
    // Each flip-flop gets specific bit from d
    q[0] <= d[15];
    q[1] <= d[14];
    q[2] <= d[13];
    q[3] <= d[12];
