module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire n0, n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n11, n12, n13, n14, n15;

  assign n0 = y[3];
  assign n1 = y[0] | y[1] | y[2] | y[3];
  assign n2 = (y[0] & y[1]) | (y[2] & y[3]);
  assign n3 = y[3] & y[2];
  assign n4 = y[3] & y[2] & y[1];
  assign n5 = ~n4;
  assign n6 = n1 & n2;
  assign n7 = n3 & y[1];
  assign n8 = n3 | y[0] | y[2];
  assign n9 = n3 | y[1] | y[2];
  assign n10 = (n1 & (y[1] | y[3])) | (n2 & (y[0] | y[2])) | (n4 & (y[0] & y[1]));
  assign n11 = n1;
  assign n12 = x[3];
  assign n13 = n10 | n6;
  assign n14 = n7 & x[3];
  assign n15 = n8 & x[3];

  assign sum[4] = (x[3] & n11) | (n13 & n14) | (x[3] & n15);
  assign sum[3] = (n9 & x[3]) | (n11 & (x[3] & n15));
  assign sum[2] = (n8 & x[3]) | (x[3] & (x[2] & x[3]));
  assign sum[1] = n7 & x[3];
  assign sum[0] = 1'bz;

endmodule

module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] sel_1;
  wire [3:0] sel_0;
  wire [3:0] sel_out;
  wire w0, w1, w2, w3, w4;
  wire and0, and1, and2;

  // Select based on least significant bit of y
  assign sel_1 = y;
  assign sel_0 = 4'b0101;
  assign sel_out = {sel_1, sel_0};

  // Top-level multiplexer
  always @(*) begin
    case (sel_out)
      4'b0000: w0 = y[0];
      4'b0001: w0 = y[1];
      4'b0010: w0 = y[2];
      4'b0011: w0 = y[3];
      4'b0100: w0 = y[0] & y[1] & sel_1[0];
      4'b0101: w0 = y[0] & y[1] & sel_1[1];
      4'b0110: w0 = y[0] & y[1] & sel_1[2];
      4'b0111: w0 = y[0] & y[1] & sel_1[3];
      default: w0 = 0;
    endcase
  end

  // First level of logic gates for w0
  assign and0 = y[1] & y[2];
  assign and1 = y[0] & y[1];
  assign and2 = y[0] & y[2];

  // Middle circuitry for w1
  assign w1 = w0 | and0 | and1 | and2;

  // Additional combinational logic
  assign w2 = w1 & y[3];
  assign w3 = w1 & y[2] & y[1];
  assign w4 = w1 & y[1] & y[0];

  // Output selection
  assign sum[0] = w1[0] | w2[0] | w3[0] | w4[0];
  assign sum[1] = w1[1] | w2[1] | w3[1] | w4[1];
  assign sum[2] = w1[2] | w2[2] | w3[2] | w4[2];
  assign sum[3] = w1[3] | w2[3] | w3[3] | w4[3];
  assign sum[4] = w2[4] | w3[4] | w4[4];

endmodule

