  assign e = (y[1] ^ x[1]) & (y[2] ^ x[2]) & (y[3] ^ x[3]);
  assign f = (y[0] ^ x[0]) & (y[1] ^ x[1]) & (y[2] ^ x[2]);
  assign g = (y[0] ^ x[0]) & (y[1] ^ x[1]) & (y[3] ^ x[3]);
  assign h = (y[0] ^ x[0]) & (y[2] ^ x[2]) & (y[3] ^ x[3]);
