  assign j = (y[0] ^ x[0]) & (y[3] ^ x[3]) & (y[1] & y[2]);
  assign k = (y[0] ^ x[0]) & (y[3] ^ x[3]) & (y[1] ^ x[1]);
  assign l = (y[0] ^ x[0]) & (y[3] ^ x[3]) & (y[2] ^ x[2]);
  assign m = (y[0] ^ x[0]) & (y[3] ^ x[3]) & (y[2] & x[1]);
