  assign p = (y[0] ^ x[0]) & (~y[1]) & y[2] & (~x[1] & x[3]);
  assign q = (y[0] ^ x[0]) & y[1] & ~y[2] & (~x[1] & x[3]);
  assign r = (y[0] ^ x[0]) & (~y[1] & y[2]) & (x[1] ^ x[3]);
  assign t = (y[0] ^ x[0]) & y[1] & (~y[2]) & (x[1] ^ x[3]);
  assign u = (y[0] ^ x[0]) & (~y[2] & y[3]) & (x[1] ^ x[2]);
  assign v = (y[0] ^ x[0]) & y[2] & (~y[3]) & (x[1] ^ x[2]);
  assign w = (y[0] ^ x[0]) & (~y[3]) & y[2] & x[1];
  assign x = (y[0] ^ x[0]) & y[3] & ~y[2] & x[1];
  assign y = (y[0] ^ x[0]) & (~y[1]) & y[3] & (~x[1] & x[2]);
