  assign dd = (y[0] ^ x[0]) & y[1] & ~y[3] & (~x[1] & ~x[3]);

  assign sum[4] = (e | f | g) | h | i | j | k | l | m | n | o | p | q | r | t | u | v | w | x | y | z | aa | bb | cc | dd;

