  wire S_SDFP_NO_Q0;
  wire S_SDFP_NO_D1;
  wire S_SDFP_NO_Q1;
  wire S_SDFP_NO_D2;
  wire S_SDFP_NO_Q2;
  wire S_SDFP_NO_D3;
  wire S_SDFP_NO_Q3;

  // First register instance (leftmost)
  assign S_SDFP_NO_D0 = in;
  assign S_SDFP_NO_Q0 = in; // Q output same as D if R is inactive

  // Second register instance
  assign S_SDFP_NO_D1 = S_SDFP_NO_Q0;
  assign S_SDFP_NO_Q1 = S_SDFP_NO_Q0;

  // Third register instance
  assign S_SDFP_NO_D2 = S_SDFP_NO_Q1;
  assign S_SDFP_NO_Q2 = S_SDFP_NO_Q1;

  // Fourth register instance (rightmost)
  assign S_SDFP_NO_D3 = clk;
  assign S_SDFP_NO_Q3 = out;

  // Regsiter instantiation (using always block with sequential logic)
  always @(posedge resetn) begin
    S_SDFP_NO_D0 <= in;
  always @(posedge clk) begin
    S_SDFP_NO_Q0 <= S_SDFP_NO_D0;
  end
  always @(posedge S_SDFP_NO_Q0) begin
    S_SDFP_NO_Q1 <= S_SDFP_NO_Q1;
  end
  always @(posedge S_SDFP_NO_Q1) begin
    S_SDFP_NO_Q2 <= S_SDFP_NO_Q2;
  end
  always @(posedge S_SDFP_NO_Q2) begin
    S_SDFP_NO_Q3 <= S_SDFP_NO_D3;
  end
  out <= S_SDFP_NO_Q3;
end

