  input ena,
  input [3:0] data,
  output reg [3:0] q
);

always @(posedge clk or posedge areset or posedge load or posedge ena) begin
    q[0] = data[0];
    q[1] = (clk & !areset) ? data[1] : data[2];
    q[2] = (clk & !areset & !load) ? data[3] : data[0];
    q[3] = (clk & !areset & !load & !ena) ? data[1] : ((clk & areset) ? data[2] : data[3]);
end

endmodule

modport TopModule (
  input clk,
  input areset,
  input load,
  input ena,
  input [3:0] data,
  output reg [3:0] q
);

always @(posedge data[3]) begin
  q[3] <= {q[2:0], clk};
  q[2] <= ({q[1:0], areset}) & (~load);
  q[1] <= ({q[0], ena}) & load;
  q[0] <= q[3];
end

endmodule

