        1: out[i] = val_1_1 & (~val_2_1);
        2: out[i] = val_1_2 & (~val_2_2);
        3: out[i] = val_1_3 & (~val_2_3);
        default: out[3] = 1'b0;
      endcase
  end
endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire u0, u1, u2;

  S_SDFF_PP0 logic_box_0 (
    .C(u0),
    .D(clk),
    .Q(rst)
  );

  S_SDFF_PP0 logic_box_1 (
    .C(u1),
    .D(u0),
    .Q(u2)
  );

  S_SDFF_PP0 logic_box_2 (
    .C(u1),
    .D(rst),
    .Q(rst)
  );

  S_SDFF_PP0 logic_box_3 (
    .C(u2),
    .D(u1 ^ u2),
    .Q(u2)
  );

  S_SDFF_PP0 logic_box_4 (
    .C(u2),
    .D(u2),
    .Q(out[0:2])
  );

  assign out[3] = rst;

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire P, Q, R;

  // clk -> P
  assign P = clk;

  // rst -> Q (connected to D of first flip-flop)
  // This is a feedback loop, so we need to model it as state
  wire q_0, q_1, q_2, q_3;

  // First flip-flop: D = rst
  always @(posedge clk or negedge rst) begin
    if (!rst)
      q_0 = 1'b0;
    else
      q_0 <= rst;
  end

  // Second flip-flop: D = q_0
  always @(posedge clk or negedge rst) begin
    if (!rst)
      q_1 = 1'b0;
    else
      q_1 <= q_0;
  end

  // Third flip-flop: D = q_1
  always @(posedge clk or negedge rst) begin
    if (!rst)
      q_2 = 1'b0;
    else
      q_2 <= q_1;
  end

  // Fourth flip-flop: D = q_2 with XNOR gate input
  always @(posedge clk or negedge rst) begin
    if (!rst)
      q_3 = 1'b0;
    else
      q_3 <= (q_1 === q_2) ? 1'b1 : 1'b0;
  end

  // Output assigned to 4-bit vector
  assign out = {q_3, q_2, q_1, q_0};

endmodule

