);

always @(pos_edge_clk) begin
	case(data_in)
		0: begin
			dataout[0] <= arstn & data_en;
			dataout[1] <= clk_b | clk_a;
			dataout[2] <= ~clk_b & clk_a;
			dataout[3] <= arstn & ~data_en;
		end
		1: begin
			dataout[0] <= clk_a;
			dataout[1] <= clk_b;
			dataout[2] <= brstn;
			dataout[3] <= arstn;
		end
