		end
		3: begin
			dataout[0] <= clk_b;
			dataout[1] <= clk_a;
			dataout[2] <= arstn;
			dataout[3] <= data_in[3];
		end
		default: begin
			dataout[0] <= 1'b0;
			dataout[1] <= 1'b0;
			dataout[2] <= 1'b0;
			dataout[3] <= 1'b0;
		end
	endcase
end

